class MCTask:
    def __init__(self, c_LO, c_HI, f, p, chi):
        self.c_LO = c_LO
        self.c_HI = c_HI
        self.f = f # failure probability
        self.p = p # period
        self.chi = chi # criticality

class MCInstance:
    def __init__(self, tasks, F_S):
        self.tasks = tasks
        self.F_S = F_S

def check_schedulability_type(instance, strategy):
    prob_any_miss = strategy.calculate_failure_prob(instance)
    if prob_any_miss < instance.F_S:
        return 'Strongly Probabilistic Schedulable'

    prob_hi_miss = strategy.calculate_hi_failure_prob(instance)
    if prob_hi_miss < instance.F_S:
        return 'Weakly Probabilistic Schedulable'

    return 'Unknown'

def get_additional_utilization(task):
    if task.chi == 'LO':
        return 0
    return (task.c_HI - task.c_LO) / task.p

def compute_cluster_failure_prob(cluster_tasks):
    prob_zero_overruns = 1.0
    for task in cluster_tasks:
        prob_zero_overruns *= (1 - task.f)

    prob_one_overrun = 0.0
    for j in range(len(cluster_tasks)):
        term = cluster_tasks[j].f
        for i in range(len(cluster_tasks)):
            if i != j:
                term *= (1 - cluster_tasks[i].f)
        prob_one_overrun += term

    return 1 - prob_zero_overruns - prob_one_overrun

def LFF_Clustering(hi_tasks, F_S):
    hi_tasks.sort(key=lambda x: x.delta, reverse=True)
    clusters = []
    M = len(hi_tasks) # Initial guess for M

    for task in hi_tasks:
        placed = False
        for cluster in clusters:
            if can_add_to_cluster(cluster, task, F_S, len(clusters)):
                cluster.append(task)
                placed = True
                break
        if not placed:
            clusters.append([task])

    delta_total = sum(max(t.delta for t in c) for c in clusters)
    return delta_total

def pMC_test(instance):
    delta_total = LFF_Clustering(instance.tasks, instance.F_S)
    U_LO_all = sum(t.c_LO / t.p for t in instance.tasks)

    if U_LO_all + delta_total <= 1.0:
        return 'Strongly Probabilistic Schedulable'

    U_HI_LO = sum(t.c_LO / t.p for t in instance.tasks if t.chi == 'HI')
    if U_HI_LO + delta_total <= 1.0 and check_theorem_1(instance.tasks, delta_total):
        return 'Weakly Probabilistic Schedulable'

    return 'Unknown'
